'use strict';

const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');

const PROJECTS_DIR = path.join(__dirname, '..', 'Projects');
if (!fs.existsSync(PROJECTS_DIR)) {
  try { fs.mkdirSync(PROJECTS_DIR, { recursive: true }); } catch (e) {}
}

const AppStudioEngine = {
  getProjectsDir() {
    return PROJECTS_DIR;
  },

  listProjects() {
    try {
      if (!fs.existsSync(PROJECTS_DIR)) return [];
      const entries = fs.readdirSync(PROJECTS_DIR, { withFileTypes: true });
      return entries
        .filter(d => d.isDirectory())
        .map(d => {
          const projectPath = path.join(PROJECTS_DIR, d.name);
          const metaPath = path.join(projectPath, 'myraa_project.json');
          let meta = { name: d.name, type: 'web_application', createdAt: new Date().toISOString() };
          if (fs.existsSync(metaPath)) {
            try { meta = JSON.parse(fs.readFileSync(metaPath, 'utf8')); } catch (e) {}
          }
          return {
            id: d.name,
            name: meta.name || d.name,
            description: meta.description || 'Generated by MYRAA App Studio',
            type: meta.type || 'Web Application',
            path: projectPath,
            hasIndex: fs.existsSync(path.join(projectPath, 'index.html')),
            hasPrd: fs.existsSync(path.join(projectPath, 'PRD.md')),
            createdAt: meta.createdAt || meta.timestamp || new Date().toISOString()
          };
        });
    } catch (err) {
      console.error('[AppStudioEngine] Error listing projects:', err);
      return [];
    }
  },

  createProject(input) {
    const rawName = String(input.appName || input.name || 'myraa-app-' + Date.now()).trim();
    const slug = rawName.toLowerCase().replace(/[^a-z0-9_-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'app-' + Date.now();
    const projectDir = path.join(PROJECTS_DIR, slug);

    if (!fs.existsSync(projectDir)) {
      fs.mkdirSync(projectDir, { recursive: true });
    }

    const type = input.type || (input.action === 'create_mobile_app' ? 'Mobile App (PWA/Capacitor)' : 'Web Application');
    const prompt = input.prompt || input.idea || (slug.replace(/-/g, ' ') + ' application');
    const designSystem = input.designSystem || 'Aceternity Glassmorphism & Cyber Modern';

    // 1. Generate Full PRD
    const prdContent = `# Product Requirement Document (PRD) — ${rawName}
**Generated by**: MYRAA AI OS v5.2 Enterprise Multimodal App Studio  
**Date**: ${new Date().toLocaleDateString()} | **Type**: ${type}  
**Design System**: ${designSystem}

## 1. Executive Summary & Vision
${rawName} is a state-of-the-art ${type.toLowerCase()} designed to deliver seamless user experience, responsive micro-animations, and full cross-platform compatibility. Built from the prompt: "${prompt}".

## 2. Core User Personas & Problems Solved
- **Primary Persona**: Power users seeking intuitive, fast, and aesthetically stunning workflows.
- **Key Pain Point**: Fragmented, slow, and uninspired interfaces that lack modern fluid interactions.
- **Value Proposition**: Instant load times, glassmorphic sci-fi aesthetic, and robust offline-first capabilities.

## 3. High-Priority Functional Requirements (EARS Format)
- **WHEN** the user opens the application, **THE SYSTEM SHALL** render the responsive navigation hero within 200ms with ambient gradient glow.
- **WHILE** the user interacts with action cards, **THE SYSTEM SHALL** provide tactile hover elevation and 3D tilting effects.
- **WHERE** data is modified, **THE SYSTEM SHALL** persist changes to localStorage and display real-time toast notifications.

## 4. Design System & Tokens
- **Theme**: Deep Void Dark (\`#050814\`, \`#0b1220\`) with Cyan (\`#00e5ff\`) and Purple/Indigo (\`#818cf8\`) neon highlights.
- **Typography**: Space Grotesk / Inter system fallback.
- **Components**: BentoGrid Layout, 3D Hero Spotlight, Dynamic Navigation, Floating Action Buttons.

## 5. Architecture & Tech Stack
- **Structure**: Standalone Zero-Dependency Single-Page Architecture (HTML5 + Modern ES6 Modules + Tailwind CDN + Lucide Icons).
- **Deployment**: Ready for instant browser launch, Electron packaging, or Tauri embedding.
`;
    fs.writeFileSync(path.join(projectDir, 'PRD.md'), prdContent, 'utf8');

    // 2. Generate Working HTML5 Application with Aceternity-inspired styling
    const appHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${rawName} — MYRAA App Studio</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&family=Space+Grotesk:wght@400;600;700&display=swap" rel="stylesheet">
  <style>
    body {
      font-family: 'Outfit', sans-serif;
      background: radial-gradient(circle at 50% 0%, #111827 0%, #030712 100%);
      color: #f3f4f6;
      min-height: 100vh;
      overflow-x: hidden;
    }
    .font-display { font-family: 'Space Grotesk', sans-serif; }
    .glass-panel {
      background: rgba(17, 24, 39, 0.7);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
    }
    .glass-panel:hover {
      border-color: rgba(0, 229, 255, 0.4);
      box-shadow: 0 8px 32px 0 rgba(0, 229, 255, 0.15);
    }
    .glow-cyan {
      box-shadow: 0 0 25px rgba(0, 229, 255, 0.35);
    }
    .bento-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 1.5rem;
    }
  </style>
</head>
<body class="p-6 md:p-12 selection:bg-cyan-500 selection:text-black">
  <!-- Ambient Top Glow -->
  <div class="fixed top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-gradient-to-b from-cyan-500/15 via-indigo-500/10 to-transparent blur-3xl pointer-events-none"></div>

  <div class="max-w-6xl mx-auto space-y-10 relative z-10">
    <!-- Header -->
    <header class="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-6 border-b border-white/10">
      <div class="space-y-1">
        <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono text-cyan-400 bg-cyan-400/10 border border-cyan-400/20">
          <span class="w-2 h-2 rounded-full bg-cyan-400 animate-pulse"></span>
          MYRAA APPS v5.2 • ACTIVE
        </div>
        <h1 class="text-3xl md:text-5xl font-display font-extrabold tracking-tight text-white mt-2">${rawName}</h1>
        <p class="text-slate-400 text-sm md:text-base">${prompt}</p>
      </div>
      <div class="flex items-center gap-3">
        <button onclick="alert('Exporting project source files...')" class="px-4 py-2 rounded-xl text-xs font-mono glass-panel hover:bg-white/10 transition">Export ZIP</button>
        <button onclick="saveProjectData()" class="px-5 py-2.5 rounded-xl text-xs font-mono font-bold text-black bg-cyan-400 hover:bg-cyan-300 transition glow-cyan">Save Changes</button>
      </div>
    </header>

    <!-- Bento Grid Showcase -->
    <section class="space-y-4">
      <div class="text-xs font-mono uppercase tracking-widest text-cyan-400">Interactive Bento Dashboard</div>
      <div class="bento-grid">
        <!-- Card 1: Core Action -->
        <div class="glass-panel p-6 rounded-2xl space-y-4 md:col-span-2">
          <div class="flex items-center justify-between">
            <span class="text-xs font-mono text-cyan-300">Feature 01 // Intelligent Core</span>
            <span class="text-xs text-slate-500 font-mono">Real-time</span>
          </div>
          <h3 class="text-xl font-display font-semibold text-white">Dynamic Workflow Pipeline</h3>
          <p class="text-slate-400 text-sm leading-relaxed">
            This module processes prompt directives and maintains context across states. Connect external APIs or integrate real-time camera and vision streams.
          </p>
          <div class="flex items-center gap-3 pt-2">
            <input type="text" id="userInput" placeholder="Test dynamic state updates..." class="flex-1 px-4 py-2 rounded-xl bg-black/40 border border-white/10 text-sm text-white focus:outline-none focus:border-cyan-400">
            <button onclick="handleAction()" class="px-4 py-2 rounded-xl text-sm font-mono bg-white/10 hover:bg-white/20 transition">Execute</button>
          </div>
          <div id="outputLog" class="p-3 rounded-xl bg-black/50 border border-white/5 font-mono text-xs text-slate-300 hidden"></div>
        </div>

        <!-- Card 2: Analytics / Metrics -->
        <div class="glass-panel p-6 rounded-2xl space-y-4">
          <div class="flex items-center justify-between">
            <span class="text-xs font-mono text-purple-300">Feature 02 // Performance</span>
            <span class="text-xs text-emerald-400 font-mono">100% OK</span>
          </div>
          <h3 class="text-xl font-display font-semibold text-white">System Metrics</h3>
          <div class="space-y-3 pt-1 font-mono text-xs">
            <div>
              <div class="flex justify-between text-slate-400 mb-1">
                <span>Memory Efficiency</span>
                <span class="text-cyan-400">98.4%</span>
              </div>
              <div class="w-full bg-white/10 h-1.5 rounded-full overflow-hidden">
                <div class="bg-cyan-400 h-full rounded-full" style="width: 98%"></div>
              </div>
            </div>
            <div>
              <div class="flex justify-between text-slate-400 mb-1">
                <span>UI Responsiveness</span>
                <span class="text-purple-400">120 FPS</span>
              </div>
              <div class="w-full bg-white/10 h-1.5 rounded-full overflow-hidden">
                <div class="bg-purple-400 h-full rounded-full" style="width: 100%"></div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- Footer -->
    <footer class="pt-8 border-t border-white/10 flex items-center justify-between text-xs font-mono text-slate-500">
      <span>Architected by MYRAA Autonomous Cognitive Mind</span>
      <span class="text-cyan-400">Status: Verified Enterprise Build</span>
    </footer>
  </div>

  <script>
    function handleAction() {
      const val = document.getElementById('userInput').value.trim();
      const out = document.getElementById('outputLog');
      if (!val) return;
      out.classList.remove('hidden');
      out.innerHTML = \`<span class="text-cyan-400">✓ Executed:</span> \${val} — \${new Date().toLocaleTimeString()}\`;
      document.getElementById('userInput').value = '';
    }
    function saveProjectData() {
      localStorage.setItem('${slug}_data', JSON.stringify({ savedAt: new Date().toISOString() }));
      alert('✓ Project state successfully saved locally.');
    }
  </script>
</body>
</html>`;
    fs.writeFileSync(path.join(projectDir, 'index.html'), appHtml, 'utf8');

    // 3. Save Project Metadata
    const meta = {
      id: slug,
      name: rawName,
      type,
      prompt,
      designSystem,
      path: projectDir,
      createdAt: new Date().toISOString()
    };
    fs.writeFileSync(path.join(projectDir, 'myraa_project.json'), JSON.stringify(meta, null, 2), 'utf8');

    return {
      success: true,
      project: meta,
      message: `Created app "${rawName}" in Projects/${slug}`
    };
  },

  openProjectInExplorer(projectId) {
    const projectDir = path.join(PROJECTS_DIR, projectId);
    if (!fs.existsSync(projectDir)) return { ok: false, error: 'Project folder does not exist' };
    exec(`explorer "${projectDir}"`);
    return { ok: true, message: `Opened project in File Explorer: ${projectDir}` };
  },

  launchProjectInBrowser(projectId) {
    const projectDir = path.join(PROJECTS_DIR, projectId);
    const htmlPath = path.join(projectDir, 'index.html');
    if (!fs.existsSync(htmlPath)) return { ok: false, error: 'index.html does not exist' };
    exec(`start "" "${htmlPath}"`);
    return { ok: true, message: `Launched ${projectId} in Windows default browser` };
  },

  async learnFromReference(urlOrRepo) {
    const webFetch = require('./web_fetch_service.cjs');
    if (String(urlOrRepo).includes('github.com') || (urlOrRepo.includes('/') && !urlOrRepo.includes('.'))) {
      return await webFetch.fetchGitHubRepo(urlOrRepo);
    }
    return await webFetch.fetchWebPage(urlOrRepo);
  },

  async installSkill(skillName) {
    const terminalRunner = require('./terminal_runner.cjs');
    return await terminalRunner.run21stSkill(`skills install ${skillName || ''}`);
  },

  async runDevServer(projectId, port = 5173) {
    const terminalRunner = require('./terminal_runner.cjs');
    const projectDir = path.join(PROJECTS_DIR, projectId);
    return await terminalRunner.startDevServer(projectDir, port);
  }
};

module.exports = AppStudioEngine;
